//! Unity `ComputeShader` serialized form, generated by the `unity2rust` example from
//! `compute.unity2rust.toml`, below the imports.

#![allow(non_snake_case, non_camel_case_types)]

use rabex::objects::{ClassId, ClassIdType};

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
pub struct ComputeShader {
    pub m_Name: String,
    pub variants: Vec<ComputeShaderPlatformVariant>,
}

impl ClassIdType for ComputeShader {
    const CLASS_ID: ClassId = ClassId::ComputeShader;
}

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
pub struct ComputeShaderPlatformVariant {
    pub targetRenderer: i32,
    pub targetLevel: i32,
    pub kernels: Vec<ComputeShaderKernelParent>,
    pub constantBuffers: Vec<ComputeShaderCB>,
    pub resourcesResolved: bool,
}

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
pub struct ComputeShaderKernelParent {
    pub name: String,
    pub uniqueVariants: Vec<ComputeShaderKernel>,
    pub variantIndices: Vec<pair>,
    pub globalKeywords: Vec<String>,
    pub localKeywords: Vec<String>,
    pub dynamicKeywords: Vec<String>,
}

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
pub struct ComputeShaderCB {
    pub name: String,
    pub byteSize: i32,
    pub params: Vec<ComputeShaderParam>,
}

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
pub struct ComputeShaderKernel {
    pub cbVariantIndices: Vec<u32>,
    pub cbs: Vec<ComputeShaderResource>,
    pub textures: Vec<ComputeShaderResource>,
    pub builtinSamplers: Vec<ComputeShaderBuiltinSampler>,
    pub inBuffers: Vec<ComputeShaderResource>,
    pub outBuffers: Vec<ComputeShaderResource>,
    pub code: Vec<u8>,
    pub threadGroupSize: Vec<u32>,
    pub requirements: i64,
}

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
pub struct pair {
    pub first: String,
    pub second: u32,
}

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
pub struct ComputeShaderParam {
    pub name: String,
    #[serde(rename = "type")]
    pub r#type: i32,
    pub offset: u32,
    pub arraySize: u32,
    pub rowCount: u32,
    pub colCount: u32,
}

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
pub struct ComputeShaderResource {
    pub name: String,
    pub generatedName: String,
    pub bindPoint: i32,
    pub samplerBindPoint: i32,
    pub texDimension: i32,
    // only in: 6000.3.27f2
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub resType: Option<i32>,
}

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
pub struct ComputeShaderBuiltinSampler {
    pub sampler: u32,
    pub bindPoint: i32,
}
